
import Link from "next/link"
import clientPromise from "@/lib/mongodb"
import { notFound } from "next/navigation";

export default async function Page({ params }) {
    const { handle } = await params
    const client = await clientPromise;
    const db = client.db("bittree")
    const collection = db.collection("links")

    const item = await collection.findOne({ handle: handle })
    if(!item){
        return notFound

    }
    const item2 = {
        links: [
            {
                link: 'https://www.youtube.com/',
                linktext: 'Youtube'
            },
            {
                link: 'https://www.instagram.com/?hl=en',
                linktext: 'Instagram'
            },
            {
                link: 'https://www.facebook.com/',
                linktext: 'Facebook'
            }
        ],
        handle: 'ayush',
        pic:
            'data:image/webp;base64,'

    }

    return <div className="flex min-h-screen bg-purple-400 justify-center text-black items-start py-8 ">

        {item && <div className="photo flex justify-center flex-col gap-3 items-center">
            <img className="h-20 w-45" src={item.pic} alt="" />
            <span className="font-bold text-xl">@{item.handle}</span>
            <span className="desc max-w-86 text-center">{item.desc}</span>
            <div className="links">
                {item.links.map((item, index) => {
                    return <Link key={index} href={item.link} > <div className="py-4 px-2 min-w-76 flex justify-center bg-purple-200 shadow-lg rounded-md my-3" >

                        {item.linktext}

                    </div>
                    </Link>

                })}
            </div>
        </div>
        }

    </div >

}